// State name to abbreviation helper
export const US_STATE_NAME_TO_ABBR = {
  'alabama': 'AL', 'alaska': 'AK', 'arizona': 'AZ', 'arkansas': 'AR', 'california': 'CA',
  'colorado': 'CO', 'connecticut': 'CT', 'delaware': 'DE', 'florida': 'FL', 'georgia': 'GA',
  'hawaii': 'HI', 'idaho': 'ID', 'illinois': 'IL', 'indiana': 'IN', 'iowa': 'IA',
  'kansas': 'KS', 'kentucky': 'KY', 'louisiana': 'LA', 'maine': 'ME', 'maryland': 'MD',
  'massachusetts': 'MA', 'michigan': 'MI', 'minnesota': 'MN', 'mississippi': 'MS', 'missouri': 'MO',
  'montana': 'MT', 'nebraska': 'NE', 'nevada': 'NV', 'new hampshire': 'NH', 'new jersey': 'NJ',
  'new mexico': 'NM', 'new york': 'NY', 'north carolina': 'NC', 'north dakota': 'ND', 'ohio': 'OH',
  'oklahoma': 'OK', 'oregon': 'OR', 'pennsylvania': 'PA', 'rhode island': 'RI', 'south carolina': 'SC',
  'south dakota': 'SD', 'tennessee': 'TN', 'texas': 'TX', 'utah': 'UT', 'vermont': 'VT',
  'virginia': 'VA', 'washington': 'WA', 'west virginia': 'WV', 'wisconsin': 'WI', 'wyoming': 'WY',
  'district of columbia': 'DC'
}

// Clean helper to find county record by (countyName, state, fips)
export function findCountyRecord(countyName = '', stateNameOrAbbr = '', fips = '') {
  const fipsStr = String(fips || '').trim().padStart(5, '0')
  if (fipsStr && fipsStr !== '00000' && SDOH_COUNTIES_BY_FIPS[fipsStr]) {
    return enrichCountyRecord(SDOH_COUNTIES_BY_FIPS[fipsStr])
  }

  const rawCounty = String(countyName || '').trim()
  const rawState = String(stateNameOrAbbr || '').trim().toLowerCase()
  const stateAbbr = US_STATE_NAME_TO_ABBR[rawState] || rawState.toUpperCase()

  // Clean county name: remove "County", "Parish", "Borough"
  const cleanCounty = rawCounty
    .replace(/\s+County$/i, '')
    .replace(/\s+Parish$/i, '')
    .replace(/\s+Borough$/i, '')
    .trim()
    .toLowerCase()

  // 1. Exact match by clean county + state abbreviation
  if (stateAbbr && cleanCounty) {
    for (const item of Object.values(SDOH_COUNTIES_BY_FIPS)) {
      if (item.state_abbr === stateAbbr && item.county_name.toLowerCase().replace(/\s+county$/i, '') === cleanCounty) {
        return enrichCountyRecord(item)
      }
    }
  }

  // 2. County name includes
  if (cleanCounty) {
    for (const item of Object.values(SDOH_COUNTIES_BY_FIPS)) {
      const itmClean = item.county_name.toLowerCase().replace(/\s+county$/i, '')
      if ((!stateAbbr || item.state_abbr === stateAbbr) && (itmClean.includes(cleanCounty) || cleanCounty.includes(itmClean))) {
        return enrichCountyRecord(item)
      }
    }
  }

  // 3. Fallback to Cuyahoga County, OH if nothing matched
  const fallback = SDOH_COUNTIES_BY_FIPS['39035'] || Object.values(SDOH_COUNTIES_BY_FIPS)[0]
  return enrichCountyRecord(fallback)
}

function enrichCountyRecord(c) {
  if (!c) return null
  const svi = c.svi_overall || 0.50

  // Category scores from real county values (0 to 1 scale for UI)
  // Higher percentage = higher protection / barrier index as formatted
  const foodScore = Math.max(0.1, Math.min(0.95, 1 - (c.food_insecurity / 45)))
  const healthcareScore = Math.max(0.1, Math.min(0.95, 1 - (c.lack_health_insurance / 30)))
  const economicScore = Math.max(0.1, Math.min(0.95, 1 - (c.poverty_rate / 40)))
  const socialScore = Math.max(0.1, Math.min(0.95, 1 - svi))
  const neighborScore = Math.max(0.1, Math.min(0.95, 1 - (c.housing_insecurity / 35)))
  const transitScore = Math.max(0.1, Math.min(0.95, 1 - (c.transportation_barrier / 25)))

  // Risk factors table items vs National Average
  const sdohTable = [
    {
      factor_name: 'Poverty Rate',
      county_value: `${c.poverty_rate}%`,
      us_avg: '11.5%',
      difference: parseFloat((c.poverty_rate - 11.5).toFixed(1)),
      unit: '%',
      category: 'Economic Stability',
      metric: 'Poverty Rate',
      value: `${c.poverty_rate}%`
    },
    {
      factor_name: 'Food Insecurity Barrier',
      county_value: `${c.food_insecurity}%`,
      us_avg: '10.4%',
      difference: parseFloat((c.food_insecurity - 10.4).toFixed(1)),
      unit: '%',
      category: 'Food Access',
      metric: 'Food Desert Population',
      value: `${c.food_insecurity}%`
    },
    {
      factor_name: 'Uninsured Rate (No Coverage)',
      county_value: `${c.lack_health_insurance}%`,
      us_avg: '8.6%',
      difference: parseFloat((c.lack_health_insurance - 8.6).toFixed(1)),
      unit: '%',
      category: 'Healthcare Access',
      metric: 'Uninsured Population',
      value: `${c.lack_health_insurance}%`
    },
    {
      factor_name: 'Transportation Barrier',
      county_value: `${c.transportation_barrier}%`,
      us_avg: '7.8%',
      difference: parseFloat((c.transportation_barrier - 7.8).toFixed(1)),
      unit: '%',
      category: 'Transportation',
      metric: 'Households without Vehicle',
      value: `${c.transportation_barrier}%`
    },
    {
      factor_name: 'Severe Housing Cost Burden',
      county_value: `${c.housing_insecurity}%`,
      us_avg: '12.1%',
      difference: parseFloat((c.housing_insecurity - 12.1).toFixed(1)),
      unit: '%',
      category: 'Neighborhood & Housing',
      metric: 'Severe Housing Cost Burden',
      value: `${c.housing_insecurity}%`
    }
  ]

  // Health outcomes table items vs National Average
  const healthTable = [
    {
      condition_name: 'Diabetes Prevalence',
      county_prevalence: `${c.diabetes_prevalence}%`,
      us_avg: '9.8%',
      difference: parseFloat((c.diabetes_prevalence - 9.8).toFixed(1)),
      condition: 'Diabetes Prevalence',
      rate: `${c.diabetes_prevalence}%`,
      national_avg: '9.8%'
    },
    {
      condition_name: 'Hypertension (High BP)',
      county_prevalence: `${c.high_bp_prevalence}%`,
      us_avg: '29.7%',
      difference: parseFloat((c.high_bp_prevalence - 29.7).toFixed(1)),
      condition: 'Hypertension',
      rate: `${c.high_bp_prevalence}%`,
      national_avg: '29.7%'
    },
    {
      condition_name: 'Coronary Heart Disease',
      county_prevalence: `${c.heart_disease_prevalence}%`,
      us_avg: '5.9%',
      difference: parseFloat((c.heart_disease_prevalence - 5.9).toFixed(1)),
      condition: 'Coronary Heart Disease',
      rate: `${c.heart_disease_prevalence}%`,
      national_avg: '5.9%'
    },
    {
      condition_name: 'Adult Obesity Rate',
      county_prevalence: `${c.obesity_prevalence}%`,
      us_avg: '33.0%',
      difference: parseFloat((c.obesity_prevalence - 33.0).toFixed(1)),
      condition: 'Adult Obesity',
      rate: `${c.obesity_prevalence}%`,
      national_avg: '33.0%'
    },
    {
      condition_name: 'Adult Tobacco Smoking',
      county_prevalence: `${c.smoking_prevalence}%`,
      us_avg: '14.4%',
      difference: parseFloat((c.smoking_prevalence - 14.4).toFixed(1)),
      condition: 'Adult Tobacco Smoking',
      rate: `${c.smoking_prevalence}%`,
      national_avg: '14.4%'
    }
  ]

  // Top SDOH barriers
  const barriers = []
  if (c.food_insecurity > 15.0) barriers.push(`Food Insecurity (${c.food_insecurity}%)`)
  if (c.poverty_rate > 15.0) barriers.push(`Poverty Barrier (${c.poverty_rate}%)`)
  if (c.lack_health_insurance > 9.5) barriers.push(`High Uninsured Rate (${c.lack_health_insurance}%)`)
  if (c.transportation_barrier > 9.0) barriers.push(`Transit Barriers (${c.transportation_barrier}%)`)
  if (c.housing_insecurity > 15.0) barriers.push(`Housing Instability (${c.housing_insecurity}%)`)
  if (!barriers.length) barriers.push('Moderate Socioeconomic Barriers', 'Primary Care Navigation Need')

  return {
    ...c,
    overall_risk_score: svi,
    overall_risk_category: c.sdoh_band || (svi > 0.70 ? 'High' : svi > 0.40 ? 'Medium' : 'Low'),
    scores: {
      healthcare_access: Math.round(healthcareScore * 100) / 100,
      social_context: Math.round(socialScore * 100) / 100,
      food_security: Math.round(foodScore * 100) / 100,
      neighborhood_environment: Math.round(neighborScore * 100) / 100,
      economic_stability: Math.round(economicScore * 100) / 100,
      education_access: Math.round((1 - svi * 0.5) * 100) / 100
    },
    sdoh_barriers: barriers,
    sdohTable,
    healthTable
  }
}

// Dynamic clinical risk calculator combining patient vitals + location dataset
export function calculateDynamicRisks(vitals = {}, countyData = null) {
  const c = countyData || findCountyRecord('Cuyahoga County', 'OH')
  const svi = c.svi_overall || 0.50

  // 1. Clinical indicators
  const age = parseFloat(vitals.age) || 45
  const sysBp = parseFloat(vitals.systolic_bp) || (vitals.hypertension === 'Yes' ? 145 : 120)
  const hba1c = parseFloat(vitals.hba1c) || (vitals.diabetes === 'Yes' ? 8.2 : 5.6)
  const glucose = parseFloat(vitals.fasting_glucose) || (vitals.diabetes === 'Yes' ? 150 : 95)
  const bmi = parseFloat(vitals.bmi) || 24.5
  const isSmoker = vitals.smoking_status === 'Current' || vitals.smoking_status === 'Yes'

  // Location baseline from county dataset prevalence
  const baseDiab = c.diabetes_prevalence / 100
  const baseBp = c.high_bp_prevalence / 100
  const baseHeart = c.heart_disease_prevalence / 100

  // Multipliers based on patient vitals
  let diabProb = baseDiab * 0.9
  if (hba1c >= 7.0 || glucose >= 140) diabProb += 0.38
  else if (hba1c >= 6.0 || glucose >= 110) diabProb += 0.18
  if (bmi >= 30) diabProb += 0.12
  if (vitals.diabetes === 'Yes') diabProb = Math.max(diabProb, 0.78)

  let bpProb = baseBp * 0.8
  if (sysBp >= 140) bpProb += 0.32
  else if (sysBp >= 130) bpProb += 0.16
  if (age > 50) bpProb += 0.10
  if (vitals.hypertension === 'Yes') bpProb = Math.max(bpProb, 0.75)

  let heartProb = baseHeart * 1.0
  if (sysBp >= 140 && hba1c >= 6.5) heartProb += 0.22
  if (isSmoker) heartProb += 0.14
  if (age > 55) heartProb += 0.12
  if (vitals.heart_disease === 'Yes') heartProb = Math.max(heartProb, 0.70)

  let asthmaProb = 0.08 + (svi * 0.08)
  if (isSmoker) asthmaProb += 0.10
  if (vitals.asthma === 'Yes') asthmaProb = Math.max(asthmaProb, 0.65)

  // Clamp probabilities 0.05 to 0.95
  const clamp = (v) => Math.min(0.95, Math.max(0.05, parseFloat(v.toFixed(2))))

  const riskScores = {
    diabetes: clamp(diabProb),
    hypertension: clamp(bpProb),
    heart_disease: clamp(heartProb),
    asthma: clamp(asthmaProb)
  }

  // Calculate patient overall health score (0-100)
  const avgRisk = (riskScores.diabetes + riskScores.hypertension + riskScores.heart_disease + riskScores.asthma) / 4
  const healthScore = Math.round(100 - (avgRisk * 50) - (svi * 20))
  const healthGap = Math.round(80 - healthScore)

  return {
    risk_scores: riskScores,
    risk_levels: {
      diabetes: riskScores.diabetes > 0.6 ? 'High' : (riskScores.diabetes > 0.3 ? 'Medium' : 'Low'),
      hypertension: riskScores.hypertension > 0.6 ? 'High' : (riskScores.hypertension > 0.3 ? 'Medium' : 'Low'),
      heart_disease: riskScores.heart_disease > 0.6 ? 'High' : (riskScores.heart_disease > 0.3 ? 'Medium' : 'Low'),
      asthma: riskScores.asthma > 0.6 ? 'High' : (riskScores.asthma > 0.3 ? 'Medium' : 'Low')
    },
    healthScore: Math.max(25, Math.min(95, healthScore)),
    healthGap: Math.abs(healthGap),
    healthGapDirection: healthGap >= 0 ? 'below' : 'above'
  }
}
